mapper.select:
SELECT id,code, qc_type AS qcType, exist_report AS existReport, disabled, approve_status AS approveStatus, create_user_name AS createUserName, create_time AS createTime, update_user_name AS updateUserName, update_time AS updateTime FROM qc_rule where is_deleted=false
AND code LIKE concat('%',#{params.searchKeyword},'%')
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
create_time DESC
